p = [0.10, 0.30, 0.35, 0.45, 0.55, 0.60, 0.75, 0.90]
y = [0, 0, 0, 1, 0, 1, 1, 1]
costs = {}
for t in [0.25, 0.4, 0.5, 0.7]:
    fp = sum(s >= t and l == 0 for s, l in zip(p, y))
    fn = sum(s < t and l == 1 for s, l in zip(p, y))
    costs[t] = fp + 3 * fn
    print(t, 'FP', fp, 'FN', fn, 'cost', costs[t])
print(min(costs, key=costs.get))

from math import log
counts = {'spam': [4, 3, 0], 'ordinary': [1, 0, 5]}
prior = {'spam': 0.3, 'ordinary': 0.7}
query = [1, 1, 0]
score = {}
for c, n in counts.items():
    theta = [(k + 1) / (sum(n) + 3) for k in n]
    score[c] = prior[c]
    for t, q in zip(theta, query):
        score[c] *= t ** q
    print(c, [round(t, 4) for t in theta], round(score[c], 5), round(log(score[c]), 3))
equal = {c: s / prior[c] for c, s in score.items()}
print('equal priors', round(equal['spam'] / sum(equal.values()), 4))
print(round(score['spam'] / sum(score.values()), 4))

import math
u = [2, 1, 0]
items = {'A': [1, 0, 0], 'B': [2, 1, 2], 'C': [0, 1, 0]}
norm = lambda v: math.sqrt(sum(x * x for x in v))
cos = {}
for name, v in items.items():
    dot = sum(a * b for a, b in zip(u, v))
    cos[name] = dot / (norm(u) * norm(v))
    print(name, dot, round(cos[name], 4))
print(round(cos['B'], 4))
